SELECT * FROM (
    SELECT * FROM CHAT_LOG
    WHERE user_id = #{userId} AND user_idx = #{userIdx} AND schedule_id IS NULL
    ORDER BY created_at DESC, chat_id DESC
)
WHERE ROWNUM <= #{limit}

SELECT * FROM (
    SELECT * FROM CHAT_LOG
    WHERE schedule_id = #{scheduleId}
    ORDER BY created_at DESC, chat_id DESC
)
WHERE ROWNUM <= #{limit}

SELECT * FROM CHAT_LOG
WHERE schedule_id = #{scheduleId}
ORDER BY created_at ASC, chat_id ASC
